# frozen_string_literal: true

require_relative "../error"
require_relative "flag"
require_relative "report_file"
require_relative "run"
require_relative "survivors"

class Kimera::CLI::Mutant
  OPTIONS = Kimera::FlagTable.new(
    banner: "Usage: kimera mutant ID|KEY [--report REPORT.json]",
    flags: [
      Kimera::Flag.build(
        "--report FILE", :report, "Report generated by kimera run (default: #{Kimera::CLI::ReportFile.default})"
      ),
      Kimera::Flag.build("--rerun", :rerun, "Re-evaluate only this mutant in the current project")
    ]
  )

  def initialize(
    io: $stdout, errors: $stderr, run: Kimera::CLI::Run.new(io: io, errors: errors), survivors: Kimera::CLI::Survivors.new
  )
    @io = io
    @run = run
    @survivors = survivors
  end

  def run(argv)
    (id,), options = OPTIONS.parse(argv, { report: Kimera::CLI::ReportFile.default.to_s, rerun: false })
    chosen = identify(id)
    report = options[:report]
    options[:rerun] ? rerun(chosen, report) : @survivors.run([report, "--id", chosen])
  end

  private

  def identify(id)
    raise(Kimera::UsageError, "mutant ID is required") unless id
    id
  end

  def rerun(id, report)
    file = Kimera::CLI::ReportFile.new(report)
    row = locate(file, id)
    settings = provenance(file.document)
    @io.puts("Re-running mutant ##{row["mutant_id"]}: #{keyed(row)}")
    @run.run(arguments_for(row, settings))
  end

  def locate(file, id)
    row = file.row(id) { raise(Kimera::UsageError, "no mutant ##{id} in this report") }
    raise(Kimera::UsageError, "mutant ##{id} has no source file") unless row["file"]
    row
  end

  def provenance(document)
    document["run"] ||
      raise(Kimera::UsageError, "report has no run provenance; rerun with a report created by this Kimera version")
  end

  def keyed(row)
    row["key"] ||
      raise(Kimera::UsageError, "report has no mutant keys; regenerate it with kimera run --report, then rerun")
  end

  def arguments_for(row, settings)
    [row.fetch("file"), "--focus", keyed(row), "--framework", settings.fetch("framework", "rspec")]
      .push("--source-root", settings["source_root"]).concat(scope(settings))
      .concat(modes(settings)).concat(waived(row)).push("--no-report")
  end

  def scope(settings)
    Array(settings["tests"]).flat_map { |glob| ["--tests", glob] }
      .push("--operators", Array(settings["operators"]).join(","))
  end

  def waived(row) = row["status"] == "ignored" ? ["--evaluate-ignored"] : []

  def modes(settings)
    [settings["coverage"] == false ? "--no-coverage" : nil, settings["isolated"] ? "--isolated" : nil].compact
  end
end
